/**
 * The one primary action of a screen: its label, action, optional icon, per-action hint (FACTS-CONTRACT §8.5 d) and
 * the state of its work (D48: the action shows its own progress). [haptics] = the app's own „Vibration“ switch
 * (D105 (24)): false keeps the success pulse silent.
 */
@Immutable
data class SbPrimaryActionModel(
    val text: String,
    val onClick: () -> Unit,
    val icon: ImageVector? = null,
    val enabled: Boolean = true,
    val hint: String? = null,
    val state: SbActionState = SbActionState.Idle,
    val haptics: Boolean = true,
)

/**
 * Screen frame (D39): at most one primary action, always at the fixed bottom place, above [navigation].
 * [navigation] is an SbNavigationBar on top-level screens and null on sub-screens. [primaryActionFocus] (2026-11-01,
 * provisional, agent) lets the app move the focus to the primary action's button with [SbActionFocus.request], as
 * after removing the last entry of a list whose add action is the primary action (spec/02 §3.3).
 * D124 (5): the back lock is registered inside the content slot after app content, so content BackHandlers
 * cannot override it. The lock local also disables sebaro back keys and cancellation handlers.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
fun SbScreen(
    topBar: @Composable () -> Unit,
    modifier: Modifier = Modifier,
    primaryAction: SbPrimaryActionModel? = null,
    navigation: (@Composable () -> Unit)? = null,
    snackbarHost: @Composable () -> Unit = {},
    primaryActionFocus: SbActionFocus? = null,
    backLocked: Boolean = false,
    backLockedHint: String? = null,
    secondaryAction: (@Composable () -> Unit)? = null,
    statusText: String? = null,
    content: @Composable (PaddingValues) -> Unit,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val wideActionZone = LocalSbWideActionZone.current
    val focusRoom = remember { SbFocusRoom() }
    val scrollSpec = LocalBringIntoViewSpec.current
    val ringRoom = with(LocalDensity.current) { (t.focus.offset + t.focus.width).toPx() }
    val roomSpec = remember(scrollSpec, ringRoom, focusRoom) { SbFocusRoomSpec(scrollSpec, ringRoom, focusRoom) }
    // the sizes of this screen's own bar, for one that gives way to what the content asks; a camera brings its own
    val contentFloor = LocalSbContentFloor.current
    val ownSizes = remember { SbContentFloor() }
    val barSizes = contentFloor ?: ownSizes
    with(LocalDensity.current) {
        ownSizes.barExtra = (t.space.s3 * 2 + (t.focus.offset + t.focus.width) * 2).roundToPx()
        ownSizes.barWords = (SebaroTheme.typography.body.lineHeight.toDp() + t.space.s8).roundToPx()
    }
    SbScreenLayout(
        modifier = modifier,
        capBottom = primaryAction?.state is SbActionState.Failed,
        busyBottom = primaryAction?.state is SbActionState.Busy,
        contentFloor = contentFloor,
        barSizes = barSizes,
        topBar = {
            CompositionLocalProvider(LocalSbBackLocked provides backLocked) {
                // CHECKS.md §80: the sentence stands on the page's colour, also over content scrolled under the bar
                Column(if (backLocked) Modifier.background(c.bg) else Modifier) {
                    topBar()
                    if (backLocked) Text(backLockedHint ?: sbMessages().savingLocked,
                        Modifier.padding(start = t.spacing.gutter, end = t.spacing.gutter, top = t.space.s2, bottom = t.space.s2).semantics { liveRegion = LiveRegionMode.Polite },
                        style = SebaroTheme.typography.body, color = c.textMuted)
                }
            }
        },
        bottomBar = {
            if (primaryAction != null || secondaryAction != null || statusText != null || navigation != null) {
                val insets = if (navigation == null) {
                    WindowInsets.navigationBars.union(WindowInsets.ime)
                } else {
                    WindowInsets.navigationBars
                }
                Column(
                    Modifier
                        .fillMaxWidth()
                        .background(c.bg)
                        .drawBehind {
                            val w = t.x.layerLineWidth.toPx()
                            drawLine(t.x.layerLineColor, Offset(0f, w / 2f), Offset(size.width, w / 2f), w)
                        }
                        .windowInsetsPadding(insets),
                ) {
                    // above the action the sentence keeps 12 dp from the layer line; beside it, it is centred on it
                    val sentence: @Composable (Modifier, Boolean) -> Unit = { sentenceModifier, beside ->
                        if (statusText != null) SbWrapText(statusText, SebaroTheme.typography.body, c.textMuted,
                            sentenceModifier.padding(start = t.spacing.gutter, end = t.spacing.gutter,
                                top = if (beside) t.space.s0 else t.space.s3))
                    }
                    if (primaryAction != null) {
                        CompositionLocalProvider(LocalSbBackLocked provides backLocked, LocalSbContentFloor provides barSizes) {
                            val button: @Composable (Modifier) -> Unit = { actionModifier ->
                                SbPrimaryActionBarFocus(
                                    modifier = actionModifier,
                                    text = primaryAction.text,
                                    onClick = primaryAction.onClick,
                                    icon = primaryAction.icon,
                                    enabled = primaryAction.enabled,
                                    hint = primaryAction.hint,
                                    state = primaryAction.state,
                                    haptics = primaryAction.haptics,
                                    focus = primaryActionFocus,
                                    secondaryAction = secondaryAction,
                                )
                            }
                            if (statusText == null && !wideActionZone) button(Modifier.weight(1f, fill = false))
                            else BoxWithConstraints(Modifier.weight(1f, fill = false).fillMaxWidth()) {
                                val zone = maxWidth
                                if (zone >= 640.dp) Row(verticalAlignment = Alignment.CenterVertically) {
                                    // the action is at least 200 dp wide and as wide as its words on one line (with
                                    // the icon), at most half the zone; the 16 dp gutters stand around it
                                    val words = rememberTextMeasurer().measure(primaryAction.text,
                                        SebaroTheme.typography.bodyStrong, softWrap = false).size.width
                                    val icon = if (primaryAction.icon != null) t.size.iconLg + t.spacing.inline else t.space.s0
                                    val key = with(LocalDensity.current) { words.toDp() } + icon + t.space.s6 * 2 + t.space.s2
                                    if (statusText != null) sentence(Modifier.weight(1f), true) else Spacer(Modifier.weight(1f))
                                    Box(Modifier.width((key.coerceAtLeast(200.dp) + t.spacing.gutter * 2).coerceAtMost(zone / 2))) {
                                        button(Modifier.fillMaxWidth())
                                    }
                                } else Column {
                                    sentence(Modifier.fillMaxWidth(), false)
                                    button(Modifier.fillMaxWidth())
                                }
                            }
                        }
                    } else if (secondaryAction != null) {
                        BoxWithConstraints(Modifier.fillMaxWidth()) {
                            if (maxWidth >= 640.dp) Row(verticalAlignment = Alignment.CenterVertically) {
                                if (statusText != null) sentence(Modifier.weight(1f), true) else Spacer(Modifier.weight(1f))
                                Box(Modifier.width(232.dp).padding(t.spacing.gutter)) { secondaryAction() }
                            } else Column {
                                sentence(Modifier.fillMaxWidth(), false)
                                Box(Modifier.fillMaxWidth().padding(t.spacing.gutter)) { secondaryAction() }
                            }
                        }
                    } else if (statusText != null) {
                        Box(Modifier.padding(bottom = t.space.s3)) { sentence(Modifier.fillMaxWidth(), false) }
                    }
                    navigation?.invoke()
                }
            }
        },
        snackbarHost = { CompositionLocalProvider(LocalSbFocusRoom provides focusRoom, content = snackbarHost) },
        content = { padding ->
            CompositionLocalProvider(LocalSbBackLocked provides backLocked, LocalBringIntoViewSpec provides roomSpec) {
                content(padding)
                // Scaffold subcomposes content after its bars; register the lock after app handlers.
                BackHandler(enabled = backLocked) {}
            }
        },
    )
}

