private enum class SbScreenSlot { Top, Toast, Bottom, Content }

/**
 * The frame of SbScreen (CHECKS.md §85; provisional, agent), with the geometry of Material's Scaffold. Scaffold places
 * the content first, and Tab follows the order of placing, so Tab went through the content before the back button; here
 * bar, content, toast and bottom block are placed in the order they stand, and zIndex keeps the bars drawn over the
 * content. [capBottom] (a failed action, whose sentence and details can fill the window): the bottom block takes at most
 * two thirds of the window above its insets, and SbPrimaryActionBar pins the action and lets the rest scroll inside it.
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
private fun SbScreenLayout(
    modifier: Modifier,
    capBottom: Boolean,
    busyBottom: Boolean,
    contentFloor: SbContentFloor?,
    barSizes: SbContentFloor,
    topBar: @Composable () -> Unit,
    bottomBar: @Composable () -> Unit,
    snackbarHost: @Composable () -> Unit,
    content: @Composable (PaddingValues) -> Unit,
) {
    val c = SebaroTheme.colors
    val bars = WindowInsets.systemBars
    val safe = remember(bars) { MutableWindowInsets(bars) }
    val under = WindowInsets.navigationBars.union(WindowInsets.ime)
    val contentLeast = SebaroTheme.tokens.size.targetTouch + SebaroTheme.tokens.space.s2
    val barPadding = SebaroTheme.tokens.space.s3 * 2
    val keyboard = WindowInsets.ime
    Surface(
        modifier = modifier.onConsumedWindowInsetsChanged { consumed -> safe.insets = bars.exclude(consumed) },
        color = c.bg,
        contentColor = c.text,
    ) {
        SubcomposeLayout { constraints ->
            val w = constraints.maxWidth
            val h = constraints.maxHeight
            val loose = constraints.copy(minWidth = 0, minHeight = 0)
            val insets = safe
            val left = insets.getLeft(this, layoutDirection)
            val right = insets.getRight(this, layoutDirection)
            val bottomInset = insets.getBottom(this)
            // a long title scrolls inside the bar, under its first row (CHECKS.md §94)
            val top = subcompose(SbScreenSlot.Top, topBar).map { it.measure(loose.copy(maxHeight = h / 2)) }
            val toast = subcompose(SbScreenSlot.Toast, snackbarHost).map { it.measure(loose.copy(maxWidth = (w - left - right).coerceAtLeast(0), maxHeight = (h - bottomInset).coerceAtLeast(0))) }
            val topTall = top.maxOfOrNull { it.height } ?: 0
            val contentRow = contentLeast.roundToPx()
            val barPad = barPadding.roundToPx()
            // head and bar count against each other: the bar stays under all of the head, and scrolls or gives way itself
            // (CHECKS.md §94, §95)
            val below = if (capBottom) {
                val inset = under.getBottom(this)
                val body = h - inset
                // a failed bar scrolls, so it gives way to controls that cannot and to the preview, down to its action and two
                // lines of its sentence or half the window, but a key of theirs and a preview to aim with stand first: its action
                // is a new capture (CHECKS.md §95, §96)
                val most = if (contentFloor != null) {
                    val clear = body - topTall - contentFloor.px - contentFloor.preview
                    val keep = minOf(maxOf(body / 2, contentFloor.barLeast), maxOf(body - topTall - contentFloor.least - contentFloor.small, body / 3))
                    minOf(body * 2 / 3, maxOf(clear, keep))
                } else {
                    // the content's row gives way before the action and a line of its sentence: over a keyboard there is room
                    // for little else (CHECKS.md §97)
                    maxOf(minOf(body * 2 / 3, body - topTall - contentRow), barSizes.barLeast)
                }
                loose.copy(maxHeight = minOf(most + inset, h - topTall).coerceAtLeast(0))
            } else if (contentFloor != null) {
                // the other states leave the same key its room: a busy bar shows its end, a resting one its action. Work takes
                // nothing from a preview at its least height, so a capture does not make it go and come (CHECKS.md §95)
                val room = maxOf(h - topTall - contentFloor.least, h / 3)
                val work = maxOf(contentFloor.restBar, h - topTall - contentFloor.px - contentFloor.preview)
                loose.copy(maxHeight = (if (busyBottom && contentFloor.restBar > 0) minOf(room, work) else room).coerceAtLeast(0))
            } else {
                // the content keeps a row: a bar too tall scrolls, or shows its end, and a key in the content stays in reach. Counted
                // above a keyboard, and only as far as the action stands whole: it comes first (CHECKS.md §97). But over an open
                // keyboard the field being typed in comes first (D139): where the action would not stand whole, the bar makes way
                // until the keyboard closes. Work keeps its bar: it says what runs
                val inset = under.getBottom(this)
                val body = h - inset
                val free = body - topTall - contentRow
                val typing = keyboard.getBottom(this) > 0 && !busyBottom
                val most = when {
                    !typing -> maxOf(free, barSizes.action + barSizes.barExtra)
                    free >= barSizes.action + barPad -> free
                    else -> 0
                }
                loose.copy(maxHeight = minOf(h - topTall, most + inset).coerceAtLeast(0))
            }
            val bottom = subcompose(SbScreenSlot.Bottom, bottomBar).map { it.measure(below) }
            val topHeight = top.maxOfOrNull { it.height }
            val bottomHeight = bottom.maxOfOrNull { it.height }
            if (contentFloor != null && !capBottom && !busyBottom) contentFloor.restBar = bottomHeight ?: 0
            val toastHeight = toast.maxOfOrNull { it.height } ?: 0
            val toastWidth = toast.maxOfOrNull { it.width } ?: 0
            val toastUp = if (toastHeight != 0) toastHeight + (bottomHeight ?: bottomInset) else 0
            val padding = PaddingValues(
                top = (topHeight?.takeIf { it != 0 } ?: insets.getTop(this)).toDp(),
                bottom = (bottomHeight?.takeIf { it != 0 } ?: bottomInset).toDp(),
                start = (if (layoutDirection == LayoutDirection.Ltr) left else right).toDp(),
                end = (if (layoutDirection == LayoutDirection.Ltr) right else left).toDp(),
            )
            val main = subcompose(SbScreenSlot.Content) { content(padding) }.map { it.measure(loose) }
            layout(w, h) {
                top.forEach { it.place(0, 0, zIndex = 1f) }
                main.forEach { it.place(0, 0) }
                toast.forEach { it.place((w - left - right - toastWidth) / 2 + left, h - toastUp, zIndex = 2f) }
                bottom.forEach { it.place(0, h - (bottomHeight ?: 0), zIndex = 3f) }
            }
        }
    }
}

/**
 * What a screen's content and its bar need of each other (CHECKS.md §89, §94, §95): [px] the height of controls in it,
 * [least] the height that holds one of their keys with its ring, [preview] the least height of what stands above them;
 * [action] the failed bar's action, [sentence] its sentence's height, [barExtra] what stands around them, [barWords] two
 * lines of a longer sentence with the room the fade dims; [small] the preview's height that a failed bar leaves as well;
 * [restBar] the bar's height at rest.
 */
@Stable
internal class SbContentFloor {
    var px by mutableIntStateOf(0)
    var action by mutableIntStateOf(0)
    var sentence by mutableIntStateOf(0)
    var least = 0
    var preview = 0
    var small = 0
    var barExtra = 0
    var barWords = 0
    var restBar = 0
    val barLeast get() = action + barExtra + minOf(sentence, barWords)
}

internal val LocalSbContentFloor = staticCompositionLocalOf<SbContentFloor?> { null }

/** The height in px of the toast over a screen's content, written by SbToastHost (CHECKS.md §84). */
@Stable
internal class SbFocusRoom {
    var toast by mutableIntStateOf(0)
}

internal val LocalSbFocusRoom = staticCompositionLocalOf<SbFocusRoom?> { null }

/**
 * The scroll to the focus inside an SbScreen (CHECKS.md §84; provisional, agent): it stops with the focus ring's [ring]
 * px clear of the scroll area's edge and, at its far side, clear of the toast. The spec has no axis, so a horizontal
 * scroller inside the screen gets the same room while a toast stands. A part too tall for the room gets less of it.
 */
@OptIn(ExperimentalFoundationApi::class)
internal class SbFocusRoomSpec(
    private val base: BringIntoViewSpec,
    private val ring: Float,
    private val room: SbFocusRoom,
) : BringIntoViewSpec {
    override fun calculateScrollDistance(offset: Float, size: Float, containerSize: Float): Float {
        val after = ring + room.toast
        return when {
            size + ring + after <= containerSize -> base.calculateScrollDistance(offset - ring, size + ring + after, containerSize)
            // it does not fit above the toast: at the top, where the most of it shows (CHECKS.md §85)
            size + 2 * ring <= containerSize -> offset - ring
            else -> base.calculateScrollDistance(offset, size, containerSize)
        }
    }
}

