/** [SbTopBar] with a formatted [title] (§4): a document's file name marked with sbFileName breaks after - . _ /. */
@Composable
fun SbTopBar(
    title: AnnotatedString,
    modifier: Modifier = Modifier,
    subtitle: String? = null,
    topLevel: Boolean = true,
    leading: (@Composable () -> Unit)? = null,
    sign: (@Composable () -> Unit)? = null,
    status: SbRowStatus? = null,
    actions: @Composable RowScope.() -> Unit = {},
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val style = if (topLevel) ty.headline else ty.title
    val measurer = rememberTextMeasurer()
    val widest = remember(title, style, measurer) { measurer.sbWidestWord(title, style) }
    val start = if (leading == null) t.spacing.gutter else t.space.s1
    // a title too tall for its window scrolls under the keys, which stay in their row (CHECKS.md §94). Only then: a scroller
    // keeps a stop for the keys and a node for TalkBack
    var titleCut by remember { mutableStateOf(false) }
    val titleScroll = rememberScrollState()
    // D99 (1): the title stands between the leading button, the tile and the actions while its widest word fits
    // there; else (a large font scale, a demo marker among the actions) the bar keeps them in its first row and the
    // title takes a line of its own under them, gutter to gutter, so its words stay whole. TalkBack keeps the order
    // back, tile, title, actions in both forms: the bar is a traversal group and the actions come last in it
    Layout(
        content = {
            Box { leading?.invoke() }
            Box(if (sign != null) Modifier.sbStartTarget() else Modifier) { sign?.invoke() }
            Column(
                if (titleCut) {
                    Modifier
                        .sbScrollMark(titleScroll, c.borderStrong)
                        .sbScrollKeys(titleScroll)
                        .verticalScroll(titleScroll)
                } else {
                    Modifier
                },
            ) {
                val titleFocus = LocalSbFrameTitleFocus.current
                SbWrapText(title, style, c.text, Modifier.semantics { heading() }.then(
                    if (titleFocus == null) Modifier else Modifier.focusProperties { canFocus = true }
                        .focusRequester(titleFocus).focusable(),
                ))
                if (subtitle != null) SbWrapText(subtitle, ty.caption, c.textMuted)
                if (status != null) SbStatus(status.tone, word = status.word, glyph = status.glyph)
            }
            Row(
                Modifier.semantics {
                    isTraversalGroup = true
                    traversalIndex = 1f
                },
                horizontalArrangement = Arrangement.spacedBy(t.space.s3),
                verticalAlignment = Alignment.CenterVertically,
                content = actions,
            )
        },
        modifier = modifier
            .semantics { isTraversalGroup = true }
            .fillMaxWidth()
            .background(c.bg)
            .windowInsetsPadding(WindowInsets.statusBars)
            .heightIn(min = t.space.s16)
            .padding(start = start, end = t.space.s1),
    ) { measurables, constraints ->
        val gap = t.space.s3.roundToPx()
        val bar = t.space.s16.roundToPx()
        val w = constraints.maxWidth
        val loose = constraints.copy(minWidth = 0, minHeight = 0)
        val lead = measurables[0].measure(loose)
        val tile = measurables[1].measure(loose)
        val tail = measurables[3].measure(loose)
        val parts = listOf(lead, tile, tail).filter { it.width > 0 }
        val room = (w - parts.sumOf { it.width } - parts.size * gap).coerceAtLeast(0)
        // past any text, for a bar in a column that scrolls itself: a verticalScroll takes no unbounded height
        val titleMost = { above: Int -> if (constraints.hasBoundedHeight) (constraints.maxHeight - above).coerceAtLeast(0) else 32_000 }
        if (widest <= room) {
            val head = measurables[2].measure(loose.copy(minWidth = room, maxWidth = room, maxHeight = titleMost(0)))
            titleCut = titleCut && titleScroll.maxValue > 0 || head.height >= titleMost(0)
            val h = maxOf(constraints.minHeight, head.height, lead.height, tile.height, tail.height)
            layout(w, h) {
                var x = 0
                listOf(lead, tile, head, tail).forEach { p ->
                    if (p === head || p.width > 0) {
                        p.placeRelative(x, ((h - p.height) / 2f).roundToInt())
                        x += p.width + gap
                    }
                }
            }
        } else {
            val inStart = t.spacing.gutter.roundToPx() - start.roundToPx()
            val inEnd = t.spacing.gutter.roundToPx() - t.space.s1.roundToPx()
            // actions too wide beside the leading key take a row of their own, or they would lie over it (CHECKS.md §88)
            val first = listOf(lead, tile).filter { it.width > 0 }
            val stacked = first.sumOf { it.width + gap } + tail.width > w
            val top = if (stacked) maxOf(bar, lead.height, tile.height) else maxOf(bar, lead.height, tile.height, tail.height)
            val row = if (stacked) tail.height else 0
            val after = t.space.s2.roundToPx()
            // the gap under it gives way first, so a title over by next to nothing does not scroll by next to nothing
            val most = titleMost(top + row)
            val head = measurables[2].measure(loose.copy(maxWidth = (w - inStart - inEnd).coerceAtLeast(0), maxHeight = most))
            titleCut = titleCut && titleScroll.maxValue > 0 || head.height >= most
            val h = constraints.constrainHeight(maxOf(constraints.minHeight, top + row + head.height + after))
            layout(w, h) {
                var x = 0
                listOf(lead, tile).forEach { p ->
                    if (p.width > 0) {
                        p.placeRelative(x, ((top - p.height) / 2f).roundToInt())
                        x += p.width + gap
                    }
                }
                tail.placeRelative(w - tail.width, if (stacked) top else ((top - tail.height) / 2f).roundToInt())
                head.placeRelative(inStart, top + row)
            }
        }
    }
}

/** Back arrow for SbTopBar(leading = …): the 48 dp SbIconButton (below) with arrow-left; „Zurück“ from the table. */
@Composable
fun SbBackButton(onClick: () -> Unit, contentDescription: String = sbMessages().back, enabled: Boolean = true) {
    SbIconButton(SebaroIcons.Outline.ArrowLeft, contentDescription, onClick, enabled = enabled && !LocalSbBackLocked.current, focusableWhenDisabled = true)
}

@Deprecated("Binary bridge before additional options", level = DeprecationLevel.HIDDEN)
@Composable
fun SbBackButton(onClick: () -> Unit, contentDescription: String = sbMessages().back) {
    SbBackButton(onClick, contentDescription, true)
}
